"""Append a short original bridge, matching its fixed level to the existing take."""
from pathlib import Path
import argparse,json,subprocess,wave,hashlib
import numpy as np
from scipy.io import wavfile
P=Path(__file__).resolve().parents[1]
a=argparse.ArgumentParser();a.add_argument('--part',type=int,required=True);a.add_argument('--supplement',type=Path,required=True);a.add_argument('--work',type=Path,required=True);o=a.parse_args();out=o.work/f'{o.part:02}-raw.wav';meta=out.with_suffix('.json');old=json.loads(meta.read_text());assert old.get('generation_type')=='shared_block','Do not append twice';backup=o.work/f'{o.part:02}-before-supplement.wav';assert not backup.exists();backup.write_bytes(out.read_bytes());backup.with_suffix('.json').write_text(meta.read_text())
def level(path):
 r=subprocess.run(['ffmpeg','-hide_banner','-i',str(path),'-af','loudnorm=I=-19:TP=-3.5:LRA=9:print_format=json','-f','null','-'],capture_output=True,text=True,check=True);return float(json.JSONDecoder().raw_decode(r.stderr[r.stderr.rfind('{'):])[0]['input_i'])
fs,x=wavfile.read(backup);fs2,y=wavfile.read(o.supplement);assert fs==fs2==24000;x=x.astype(float)/32768;y=y.astype(float)/32768;gain=level(backup)-level(o.supplement);y*=10**(gain/20);z=np.r_[x,y];common=min(1,.97/max(np.max(np.abs(z)),1e-8));z*=common;wavfile.write(out,fs,np.rint(z*32767).astype(np.int16))
part=next(x for x in json.loads((P/'roteiro/partes.json').read_text())if x['part']==o.part);profile=json.loads((P/'audio/voice-profile.json').read_text());record={'part':o.part,'text':part['text'],'voice':profile['voice'],'model':profile['model'],'direction':profile['direction']};record['request_sha256']=hashlib.sha256(json.dumps(record,sort_keys=True).encode()).hexdigest();supp=json.loads(o.supplement.with_suffix('.json').read_text());record.update(generation_type='shared_block_plus_supplement',provider_request_sha256=old['provider_request_sha256'],supplement_request_sha256=supp['request_sha256'],source_block=old['source_block'],source_seconds_range=old['source_seconds_range'],supplement_source=o.supplement.name,supplement_static_gain_db=gain,common_gain_db=float(20*np.log10(common)),raw_seconds=len(z)/fs,source_components=[{'file':old['source_block'],'seconds_range':old['source_seconds_range']},{'file':o.supplement.name,'seconds_range':[0,len(y)/fs]}]);meta.write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n');print('SUPPLEMENT_JOINED',o.part,'seconds',len(z)/fs,'supplement_gain_db',gain,flush=True)
